package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;

final class ReadingPlan {
    static void show(ReaderActivity a){String key=BookSettings.key(a,a.uri,a.getIntent().getLongExtra("study_material",0));JSONObject saved=BookSettings.get(a,key).optJSONObject("plan");int total=Math.max(1,a.chrome.count()),current=Math.max(0,a.chrome.current());LinearLayout form=PlusUi.column(a);form.addView(PlusUi.text(a,a.kind.equals("pdf")?"Páginas por dia":"Partes por dia",14));EditText each=PlusUi.input(a,"Quantidade",saved==null?"5":""+saved.optInt("per_day",5),5);each.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);form.addView(each);if(saved!=null)form.addView(PlusUi.text(a,status(saved,current,System.currentTimeMillis()),13));form.addView(PlusUi.text(a,"O plano usa as páginas ou partes do livro. O progresso de leitura continua guardado na capa.",12));new UiDialog.Builder(a).setTitle("Plano de leitura").setView(form).setPositiveButton("Guardar",(d,w)->{try{int count=Integer.parseInt(each.getText().toString());if(count<1||count>10000)throw new IllegalArgumentException("Use uma quantidade de 1 a 10000.");PlusUi.run(a,()->{BookSettings.update(a,key,data->data.put("plan",new JSONObject().put("total",total).put("start_unit",current).put("last_unit",current).put("per_day",count).put("started",System.currentTimeMillis())));PlusUi.post(a,()->PlusUi.toast(a,"Plano de leitura guardado."));});}catch(Exception e){PlusUi.error(a,e);}}).setNeutralButton(saved==null?null:"Eliminar plano",(d,w)->PlusUi.run(a,()->BookSettings.update(a,key,data->data.remove("plan")))).setNegativeButton("Cancelar",null).show();}
    static String status(JSONObject plan,int current,long now){int total=Math.max(1,plan.optInt("total",1)),each=Math.max(1,plan.optInt("per_day",1)),start=Math.max(0,plan.optInt("start_unit",0));long elapsed=Math.max(0,(now-plan.optLong("started",now))/86400000L),days=Math.max(1,((long)total-start+each-1)/each),target=Math.min(total,start+(elapsed+1)*each);long finish=plan.optLong("started",now)+(days-1)*86400000L;return "Hoje: "+Math.min(total,current+1)+" / "+target+" · "+"Previsão: "+new java.text.SimpleDateFormat("dd/MM/yyyy",Locale.getDefault()).format(new Date(finish));}
    static void remember(ReaderActivity a){if(a.profiles==null||a.chrome==null||a.workspaceEpoch!=WorkspaceEpoch.value)return;String key=a.profiles.key;int current=a.chrome.current();a.worker.execute(()->{try{BookSettings.update(a.getApplicationContext(),key,data->{JSONObject plan=data.optJSONObject("plan");if(plan!=null)plan.put("last_unit",Math.max(plan.optInt("last_unit"),current));});}catch(Exception e){AppDiagnostics.record(a,"reading-plan",e);}});}
    private ReadingPlan(){}
}
